function IdolLive3D_BaseParamsJsonDataV2:__init( baseJsonData_, outLoaders_ )
    self.data = baseJsonData_
    self.activeKeyFuncs = {}
    self:CompleteBaseParamsJsonData( outLoaders_ )
    self.isInit1 = true
end



function IdolLive3D_BaseParamsJsonDataV2:__delete()
    --printError( "IdolLive3D_BaseParamsJsonDataV2 - Delete" )

    self.activeKeyFuncs = {}

    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end

    for _,stageJson in pairs( self.data.stages ) do 
        if stageJson.freeCameraMode == IdolLive3D_States.FreeCameraMode.PosFree then 
            if isNotNull(stageJson.freeTrackCamera.freeCameraTrackNodeParamsManager) then
                stageJson.freeTrackCamera.freeCameraTrackNodeParamsManager:Delete()
            end
        end
    end

    self.data = nil
end




-- 补完 baseParamsJsonData json 数据:
-- 将一些需要加载的资源, 直接列入 outLoaders_ 中;
-- 因为 json 文件格式在不断被修改, 但有些旧 json 文件里并未写入新变量, 故在此函数内手动补完;
---@param outLoaders_ table @ 异步加载handler容器
function IdolLive3D_BaseParamsJsonDataV2:CompleteBaseParamsJsonData( outLoaders_ ) 
    ---@type IdolLive3D_States
    local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')
    ---
    local tmpTable = {} -- 工具容器

    ---
    self.stageJump_name_to_InteractiveStates = {
        ["jump_superTimeline"] = {   -- 人造 iState: -- !! tmp
            stateType = IdolLive3D_States.InteractiveStateType.StageJump,
            name = "jump_superTimeline",
        },  
        ["jump_UI"] = {                 -- 人造 iState: -- !! tmp
            stateType = IdolLive3D_States.InteractiveStateType.StageJump,
            name = "jump_UI",
        },
        -- ... 其它 stageJumpStages; 下面会装填
    }

    ---
    ---------------- oths --------------------
    assert( isTable(self.data.oths) )

    ---------------- oths.cameraParams --------------------
    if isNull(self.data.oths.cameraParams) then 
        self.data.oths.cameraParams = {
            nearPlane = 0.05,
            farPlane = 500,
        }
    end 
    if self.data.oths.cameraParams.nearPlane == 0 then 
        self.data.oths.cameraParams.nearPlane = 0.05
    end
    if self.data.oths.cameraParams.farPlane == 0 then 
        self.data.oths.cameraParams.farPlane = 500
    end

    ---------------- oths.resources --------------------
    assert( isTable(self.data.oths.resources) )
    assert( isTable(self.data.oths.resources.fullScreenFXs) )
    assert( isTable(self.data.oths.resources.prefabs) )
    assert( isTable(self.data.oths.resources.materials) )

    ---------------- oths.resources.fullScreenFXs --------------------
    if IdolLive3D_Utils.IsEachKeyUnique(self.data.oths.resources.fullScreenFXs) == false then 
        printError("资源 fullScreenFXs 中发现重复的 key")
    end 
    for _,fx in pairs(self.data.oths.resources.fullScreenFXs) do 
        if isNull(fx.color) then 
            fx.color = Color.white
        end 
    end

    ---------------- oths.resources.prefabs --------------------
    if IdolLive3D_Utils.IsEachKeyUnique(self.data.oths.resources.prefabs) == false then 
        printError("资源 prefabs 中发现重复的 key")
    end 

    ---------------- oths.resources.materials --------------------
    if IdolLive3D_Utils.IsEachKeyUnique(self.data.oths.resources.materials) == false then 
        printError("资源 materials 中发现重复的 key")
    end 

    ---------------- oths.demo --------------------
    if isNull(self.data.oths.demo) then 
        self.data.oths.demo = { isDemo =  false }
    end 

    ---------------- oths.luaPath --------------------
    self.data.oths.skinLuaEnv = nil -- 本皮肤的定制脚本


    ---------------- oths.debugParams --------------------
    if isNull(self.data.oths.debugParams) then 
        self.data.oths.debugParams = { DisableRoleIK =  false }
    end 


    ---------------- Stages --------------------
    assert( table.count(self.data.stages) > 0 )
    --- toMap:
    tmpTable = {}
    for _,stageJson in pairs( self.data.stages ) do 
        self:_PrepareAndLoadStageClipsAsync( stageJson, outLoaders_ )
        assert( tmpTable[stageJson.stageName] == nil )
        tmpTable[stageJson.stageName] = stageJson

        --- 
        if isNull(stageJson.uiMgr) or isNull(stageJson.uiMgr.uiNodes) then 
            stageJson.uiMgr = { uiNodes = {} }
        end 
        for _,uiNode in pairs(stageJson.uiMgr.uiNodes) do 

            --- 用 key 来激活禁用某个 iState:
            if isNull(uiNode.activeKeyMgr) then 
                uiNode.activeKeyMgr = { nodes = {} }
            end
            uiNode.isCurrentActive = true 
            self:_BindActiveKeyEvent(uiNode, self.activeKeyFuncs)
        end

    end 
    self.data.stages = tmpTable -- 现在, 它变成了 map: {k:stageName,v:stage}


    --- ================== super timelines =====================
    assert( isTable(self.data.superTimelineInteractiveStates) )
    for _,iState in pairs(self.data.superTimelineInteractiveStates) do 

        assert( string.isEmpty(iState.firstClipId) == false )
        -- 触控关键词
        assert( type(iState.touchKey) == "string" ) -- 代替旧的 "desc"
        iState.interactiveType = (iState.touchKey=="") and IdolLive3D_States.InteractiveType.Spacial or IdolLive3D_States.InteractiveType.Touch
        ---
        if type(iState.maxPlayTimes) ~= "number" then 
            iState.maxPlayTimes = -1
        end
        iState.playTimes = 0

        --- 用 key 来激活禁用某个 iState:
        if isNull(iState.activeKeyMgr) then 
            iState.activeKeyMgr = { nodes = {} }
        end
        iState.isCurrentActive = true 
        self:_BindActiveKeyEvent(iState, self.activeKeyFuncs)

        --- ====
        for __,clip in pairs(iState.clips) do 
            clip.clipType = IdolLive3D_StatesV2.SuperTimelineClipType.Normal
            assert( string.isEmpty( clip.timelinePath) == false )

            if isNull(clip.fullScreenBlack) then 
                clip.fullScreenBlack = {
                    fullTime = 1,
                    isUsed = false
                }
            end 
            if clip.fullScreenBlack.isUsed and clip.fullScreenBlack.fullTime <= 0.001 then 
                printError("fullScreenBlack.fullTime 设置得太短了")
                clip.fullScreenBlack.fullTime = 1
            end
            ---
            if isNull(clip.isCloseLookAt) then 
                clip.isCloseLookAt = false
            end         
            --- 
            self:_CheckSuperTimelineClipLeaves(clip)
            ---
            if type(clip.easeInBlendTime) ~= "number" then 
                clip.easeInBlendTime = 1
            end 
            clip.easeInBlendTime = Mathf.Max( clip.easeInBlendTime, 0.0 )
            --- sceneNodes: 用来开启关闭的
            assert(isTable(clip.sceneNodesMgr))
            assert(isTable(clip.sceneNodesMgr.sceneNodes))
            ---
            assert(isTable(clip.sounds))
            self:_PrepareSoundList( clip.sounds )
            ---
            assert(isTable(clip.customParams))
            self:_PrepareCustomParams( clip.customParams )
            --- 
            for _,ikParam in pairs(clip.IKParams) do 
                self:_PrepareIKParam(ikParam)
            end 
            ---
            if isNull(clip.customFreeTrack) then 
                clip.customFreeTrack = 
                {
                    -- 别的字段暂时略;
                    isUse = false,
                } 
            end
            if clip.customFreeTrack.isUse == true then 
                IdolLive3D_BaseParamsJsonDataV2._Prepare_FreeCameraActiveSpatialRange( clip.customFreeTrack.freeCameraActiveSpatialRange ) -- !!! Must
            end

            --- 
            if isNull(clip.uiMgr) or isNull(clip.uiMgr.uiNodes) then 
                clip.uiMgr = { uiNodes = {} }
            end 
            for _,uiNode in pairs(clip.uiMgr.uiNodes) do 

                --- 用 key 来激活禁用某个 iState:
                if isNull(uiNode.activeKeyMgr) then 
                    uiNode.activeKeyMgr = { nodes = {} }
                end
                uiNode.isCurrentActive = true 
                self:_BindActiveKeyEvent(uiNode, self.activeKeyFuncs)
            end
        end 

        --- ===
        iState.clipsFakeIK = checkTable(iState.clipsFakeIK)
        for __,fClip in pairs(iState.clipsFakeIK) do 
            fClip.clipType = IdolLive3D_StatesV2.SuperTimelineClipType.FakeIK
            assert( string.isEmpty( fClip.timelinePath) == false )

            -- 兼容性考虑:
            fClip.fullScreenBlack = {
                fullTime = 1,
                isUsed = false
            }
            ---
            if isNull(fClip.isCloseLookAt) then 
                fClip.isCloseLookAt = false
            end         
            --- 
            self:_CheckSuperTimelineClipLeaves(fClip)   
            ---
            if type(fClip.easeInBlendTime) ~= "number" then 
                fClip.easeInBlendTime = 1
            end 
            fClip.easeInBlendTime = Mathf.Max( fClip.easeInBlendTime, 0.0 )
            --- sceneNodes: 用来开启关闭的
            assert(isTable(fClip.sceneNodesMgr))
            assert(isTable(fClip.sceneNodesMgr.sceneNodes))

            --- !!! 未来实现 ...
            -- assert(isTable(fClip.sounds))
            -- self:_PrepareSoundList( fClip.sounds )

            ---
            assert(isTable(fClip.customParams))
            self:_PrepareCustomParams( fClip.customParams )
            ---
            if isNull(fClip.customFreeTrack) then 
                fClip.customFreeTrack = 
                {
                    -- 别的字段暂时略;
                    isUse = false,
                } 
            end
            if fClip.customFreeTrack.isUse == true then 
                IdolLive3D_BaseParamsJsonDataV2._Prepare_FreeCameraActiveSpatialRange( fClip.customFreeTrack.freeCameraActiveSpatialRange ) -- !!! Must
            end
        end 

    
        --- toMap:
        iState.allClips = {} -- !!! clips 总容器 !!!
        tmpTable = {}
        for __,clip in pairs(iState.clips) do 
            assert( tmpTable[clip.clipId] == nil )
            tmpTable[clip.clipId] = clip
            iState.allClips[clip.clipId] = clip
        end
        iState.clips = tmpTable -- 现在, 它变成了 map: {k:clipId,v:clip}

        --- toMap:
        tmpTable = {}
        for __,fClip in pairs(iState.clipsFakeIK) do 
            assert( tmpTable[fClip.clipId] == nil )
            tmpTable[fClip.clipId] = fClip
            iState.allClips[fClip.clipId] = fClip
        end
        iState.clipsFakeIK = tmpTable -- 现在, 它变成了 map: {k:clipId,v:clip}


        if isNull(iState.enterFullScreenFXPair) then 
            iState.enterFullScreenFXPair = {
                isUsed = false
            }
        end 

        --- 本 supertimeline 用到的所有 conditionKey:
        -- map: k:strKey, v:nil or 1
        iState.allConditionKeys = self:_CollectSuperTimelineAllConditionKeys(iState) 
    end


    --- ============= 装填每个 stage 的 SuperTimelines: ==========
    for _,stage in pairs(self.data.stages) do 
        for _,key in pairs(stage.superTimelineKeys) do 
            local superTL = self:_FindSuperTimelineByKey(key)
            assert( isNotNull(superTL) )
            stage.SuperTimelines[key] = superTL
        end 
    end

    --- ============= 收集每个 stage 的 allTouchKeys: ==========
    for _,stage in pairs(self.data.stages) do 
        -- map: k:strKey, v:nil or 1
        stage.allTouchKeys = self:_CollectStageAllTouchKeys(stage)
    end

    --
    self.superTimeline_name_to_InteractiveStates = {}
    for _,iState in pairs(self.data.superTimelineInteractiveStates) do 
        self.superTimeline_name_to_InteractiveStates[iState.name] = iState
    end

    ---
    self:_MakeSureAllTimelineStateIsUnique()
end



--- baseJson 的一些延迟初始化工作:
---@param baseBGM_ table  @ {sheet="",cue=""}
function IdolLive3D_BaseParamsJsonDataV2:InitAfterSceneLoaded( baseBGM_ ) 

    -- 需要等 场景prefab 都加载进 "_Builds_" 之后:
    local buildsRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Builds_")
    assert( isNotNull(buildsRootTF) )
    --- ================== super timelines =====================
    for _,iState in pairs(self.data.superTimelineInteractiveStates) do 

        for __,clip in pairs(iState.allClips) do 
            for _,sceneNode in pairs(clip.sceneNodesMgr.sceneNodes) do 
                -- 找到的返回值装入 sceneNode.transform
                IdolLive3D_BaseParamsJsonDataV2._FindSceneNodeGO( buildsRootTF, sceneNode )
            end 
        end
    end


    -- ============= stages ==============
    -- 装备 idle 和 simple iState 的 animClipGO:
    for _,stage in pairs(self.data.stages) do 
        --[[
        printError("=== stage.animClips ===" )
        for n,v in pairs(stage.animClips) do 
            printError("name: " .. tostring(n) .. "; go: " .. tostring(v))
        end 
        printError("--------------" )
        ]]--
        stage.idleState.animClipGO = stage.animClips[StageClipNames.Idle]
        assert(isNotNull(stage.idleState.animClipGO))
        for _,iState in pairs(stage.simpleInteractiveStates) do 
            iState.animClipGO = stage.animClips[iState.name]
            if isNull(iState.animClipGO) then 
                printError("name = " .. tostring())
            end
        end

        ---
        for _,sceneNode in pairs(stage.sceneNodesMgr.sceneNodes) do 
            -- 找到的返回值装入 sceneNode.transform
            IdolLive3D_BaseParamsJsonDataV2._FindSceneNodeGO( buildsRootTF, sceneNode )
            
        end 

    end


    -- ============= stage stageJumps.tgtStageJson ==============
    for _,stageJson in pairs(self.data.stages) do 
        for _,stageJump in pairs(stageJson.stageJumps) do
            stageJump.tgtStageJson = self:GetStage(stageJump.tgtStageName)
            if isNull(stageJump.tgtStageJson) then 
                printError("没找到 stage: " .. tostring(stageJump.tgtStageName))
            end
        end
    end

    
    -- ============= 收集入场信息 ==============

    -- =====
    assert( string.isEmpty(self.data.enterMgr.InitStageName) == false )
    self.data.enterMgr.initStage = self.data.stages[self.data.enterMgr.InitStageName]
    assert( isNotNull(self.data.enterMgr.initStage) )

    -- =====
    self.firstTimelineState = nil -- 入场时需要自动播放的 timeline
    if string.isEmpty(self.data.enterMgr.InitSuperTimelineKey)==false then
        for _,iState in pairs(self.data.superTimelineInteractiveStates) do
            if iState.key == self.data.enterMgr.InitSuperTimelineKey then 
                self.firstTimelineState = iState
            end 
        end
        assert(isNotNull(self.firstTimelineState))
        -- todo ...
    end

    -- =================
    --- 确认 bgm
    assert( isNotNull(baseBGM_) )
    self.baseBGM = baseBGM_

    -- ============= stages InteractiveStates ==============
    for _,stageJson in pairs( self.data.stages ) do 
        stageJson.InteractiveStates = {} -- 包含: idle, Simples, superTimelines
        --table.insert( stageJson.InteractiveStates, stageJson.idleState )
        for _,iState in pairs(stageJson.simpleInteractiveStates) do 
            table.insert( stageJson.InteractiveStates, iState )
        end
        for _,iState in pairs(stageJson.SuperTimelines) do 
            table.insert( stageJson.InteractiveStates, iState )
        end
        --printError("InteractiveStates num = " .. tostring(table.count(stageJson.InteractiveStates)))
    end 


    -- 绑定 Events:
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        [IdolLive3D_States.EventSetActiveKey] = function(key_,isActive_)  
            for i=1, #self.activeKeyFuncs do 
                self.activeKeyFuncs[i](key_,isActive_)
            end 
        end
    })

end



----------------------------- Stage ------------------------------- 

---@param stageName_ string
---@return table | nil 
function IdolLive3D_BaseParamsJsonDataV2:GetStage( stageName_ ) 
    if self.isInit1 ~= true then 
        printError("本函数调用阶段不对")
        return nil
    end 
    if IdolLive3D_Utils.IsKeyValid(stageName_) == false then 
        printError("参数 stageName_ 异常: " .. tostring(stageName_))
        return nil
    end 
    ---
    local stage = self.data.stages[stageName_]
    if isNull(stage) then 
        printError("没找到 stage: "..tostring(stageName_))
    end 
    return stage
end 


function IdolLive3D_BaseParamsJsonDataV2:_PrepareAndLoadStageClipsAsync( stageJson_, outLoaders_ )

    local headStr = IdolLive3D_StatesV2.loaderHead_Stage .. stageJson_.stageName .. "." -- "Stage_100."

    -- ======== stageName =======
    assert( string.isEmpty(stageJson_.stageName) == false )
    
    -- ======== IdleState =======
    stageJson_.idleState.name = stageJson_.stageName
    stageJson_.idleState.stage = stageJson_ 

    -- ======== roleParams =======
    local roleParams = stageJson_.roleParams
    ---
    roleParams.customLightDir = isNull(roleParams.customLightDir) and Vector3.zero or IdolLive3D_Utils.Table2Vector3( roleParams.customLightDir ) -- 为规避有些bug 
    ---
    assert( IdolLive3D_BaseParamsJsonDataV2._IdolLive3D_LookatParams_IsNotSet(roleParams.lookatParams) == false )
    assert( IdolLive3D_BaseParamsJsonDataV2._FreeCameraSpatialRange_IsNotSet(roleParams.LookCameraSpatialRange) == false )
    ---
    roleParams.rolePos = isNull(roleParams.rolePos) and Vector3.zero or IdolLive3D_Utils.Table2Vector3(roleParams.rolePos)
    ---
    if isNull(roleParams.roleEuler) then 
        roleParams.roleEuler = Vector3.zero
    end 
    roleParams.roleRotation = Quaternion.Euler(roleParams.roleEuler)


    -- ======== freeTrackCamera =======
    -- ======== posLockedCamera =======
    assert( isNotNull(stageJson_.freeCameraMode) )
    do
        local freeCamParams = stageJson_.freeTrackCamera

        if stageJson_.freeCameraMode == IdolLive3D_States.FreeCameraMode.PosFree then 
            -- ===== 自由轨道相机 =====
            assert( IdolLive3D_BaseParamsJsonDataV2._FreeCameraSpatialParams_IsNotSet(freeCamParams.initCameraSpatialParams ) == false )                
        else 
            -- ===== pos锁定 相机 =====
            self:_HandlePosLockedCameraParams( stageJson_.posLockedCamera )
        end

        -- !!! 就算是 PosLocked 相机, 也会准备这些参数, 这是当前的 IdolLive3D_FreeCameraMgrV2 设计限制导致的
        assert( isNotNull(freeCamParams.freeCameraActiveSpatialRange) )
        IdolLive3D_BaseParamsJsonDataV2._Prepare_FreeCameraActiveSpatialRange( freeCamParams.freeCameraActiveSpatialRange )
        ---
        freeCamParams.freeTrackCenterPos = isNull(freeCamParams.freeTrackCenterPos) and Vector3.zero or IdolLive3D_Utils.Table2Vector3( freeCamParams.freeTrackCenterPos )

        -- 读取 自由相机轨道 json 文件
        assert( string.isEmpty(freeCamParams.freeTrackJsonPath) == false )
        freeCamParams.freeTrackJson = IdolLive3D_Utils.LoadJsonSync( freeCamParams.freeTrackJsonPath ) -- 比如: "Presets/IdolLive3D/FreeTrack/test1.json"
    end

    
    -- ======== idleState sounds =======
    self:_PrepareSoundList( stageJson_.idleState.sounds )

    -- ======== idleState videoSubtitle =======
    if isNull(stageJson_.idleState.videoSubtitle) then 
        stageJson_.idleState.videoSubtitle = IdolLive3D_BaseParamsJsonDataV2._GetFullVideoSubtitle()
    end 

    -- ======== idleState maxPlayTimes =======
    if type(stageJson_.idleState.maxPlayTimes) ~= "number" then 
        stageJson_.idleState.maxPlayTimes = -1
    end
    stageJson_.idleState.playTimes = 0

    -- ======== idleState IKParams =======
    for _,ikParam in pairs(stageJson_.idleState.IKParams) do 
        self:_PrepareIKParam(ikParam)
    end 

    -- ================== Simple 动作 =====================
    for _,iState in pairs(stageJson_.simpleInteractiveStates) do 
        assert( type(iState.isCloseLookAt) == "boolean" )
        ---
        assert( type(iState.fxPrefabPath) == "string" )
        if string.isEmpty(iState.fxPrefabPath) == false then 
            local name = headStr .. IdolLive3D_StatesV2.loaderHead_SimpleFX .. iState.name -- "Stage_100.SimpleFX_101"
            local path = iState.fxPrefabPath
            outLoaders_[name] = ResourceModule.LoadBundleAsync(path, nil, true) 
        end
        iState.fxTF = nil -- add
        ---
        assert( isTable(iState.videoSubtitle) )
        ---
        self:_PrepareSoundList( iState.sounds )
        -- 触控关键词
        assert( type(iState.touchKey) == "string" ) -- 代替旧的 "desc"
        iState.interactiveType = (iState.touchKey=="") and IdolLive3D_States.InteractiveType.Spacial or IdolLive3D_States.InteractiveType.Touch
        --
        if iState.interactiveType == IdolLive3D_States.InteractiveType.Spacial then 
            assert( IdolLive3D_BaseParamsJsonDataV2._FreeCameraSpatialRange_IsNotSet(iState.cameraSpatialRange) == false )
        end 

        --- 用 key 来激活禁用某个 iState:
        if isNull(iState.activeKeyMgr) then 
            iState.activeKeyMgr = { nodes = {} }
        end
        iState.isCurrentActive = true 
        self:_BindActiveKeyEvent(iState, self.activeKeyFuncs)


        if type(iState.maxPlayTimes) ~= "number" then 
            iState.maxPlayTimes = -1
        end
        iState.playTimes = 0
    end

    -- ================== 音效 动作 =====================
    stageJson_.soundInteractiveStates = checkTable(stageJson_.soundInteractiveStates)
    for i=1, table.count(stageJson_.soundInteractiveStates) do 
        local iState = stageJson_.soundInteractiveStates[i]
        if isNull(iState.name) then 
            iState.name = "sound_" .. tostring(i)
        end 
        if isNull(iState.videoSubtitle) then 
            iState.videoSubtitle = IdolLive3D_BaseParamsJsonDataV2._GetFullVideoSubtitle()
        end 
        self:_PrepareSoundList( iState.sounds )

        if type(iState.maxPlayTimes) ~= "number" then 
            iState.maxPlayTimes = -1
        end
        iState.playTimes = 0
        --- 用 key 来激活禁用某个 iState:
        if isNull(iState.activeKeyMgr) then 
            iState.activeKeyMgr = { nodes = {} }
        end
        iState.isCurrentActive = true 
        self:_BindActiveKeyEvent(iState, self.activeKeyFuncs)
    end


    -- ======== name_to_InteractiveStates =======
    stageJson_.name_to_InteractiveStates = {} -- 反解表
    stageJson_.name_to_InteractiveStates[stageJson_.idleState.name] = stageJson_.idleState

    for _,iState in pairs(stageJson_.simpleInteractiveStates) do 
        stageJson_.name_to_InteractiveStates[iState.name] = iState
    end 

    for _,iState in pairs(stageJson_.soundInteractiveStates) do 
        stageJson_.name_to_InteractiveStates[iState.name] = iState
    end 



    -- ================== SuperTimelines =====================
    stageJson_.SuperTimelines = {} -- 延后装填

    -- ======== animClips =======
    --- 初始化容器
    stageJson_.animClips = {}

    local TryLoad = function( key_, path_ )
        local fullKey = headStr .. key_ -- "Stage_100.Idle"
        if string.isEmpty(path_) == false then 
            outLoaders_[tostring(fullKey)] = ResourceModule.LoadBundleAsync(path_, nil, true)
        end 
    end


    -- ======== stageJumps =======
    --- toMap:
    local tmpTable = {}
    for _,stageJump in pairs(stageJson_.stageJumps) do
        if isNotNull(tmpTable[stageJump.tgtStageName]) then 
            printError("发现重复的 stageJump: " .. tostring(stageJump.tgtStageName))
        end 
        if not (stageJump.compareMode == IdolLive3D_States.CameraSpatialRangeCompareMode.Include or stageJump.compareMode == IdolLive3D_States.CameraSpatialRangeCompareMode.Outside) then 
            printError("stageJump compareMode 值异常: " .. tostring(stageJump.compareMode))
            stageJump.compareMode = IdolLive3D_States.CameraSpatialRangeCompareMode.Include
        end

        -- 触控关键词
        assert( type(stageJump.touchKey) == "string" ) -- 代替旧的 "desc"
        stageJump.interactiveType = (stageJump.touchKey=="") and IdolLive3D_States.InteractiveType.Spacial or IdolLive3D_States.InteractiveType.Touch
        ---
        tmpTable[stageJump.tgtStageName] = stageJump
    end 
    stageJson_.stageJumps = tmpTable -- 现在 stageJumps 变成 map 了;
    ---
    for tgtStageName,stageJump in pairs(stageJson_.stageJumps) do
        local key = headStr .. IdolLive3D_StatesV2.loaderHead_ToIdle .. tgtStageName -- "Stage_100.ToIdle_200"
        local path = stageJump.animClipPath
        ---
        if IdolLive3D_Utils.IsKeyValid(path) then 
            outLoaders_[key] = ResourceModule.LoadBundleAsync(path, nil, true)
            --- 
            local toIdleStateName = "From_" .. tostring(stageJson_.stageName) .. "_To_" ..tostring(tgtStageName) -- "From_200_To_100"
            stageJump.toIdleState = {
                stateType = IdolLive3D_States.InteractiveStateType.StageSmoothSwitch,
                name = toIdleStateName,
            }
            self.stageJump_name_to_InteractiveStates[toIdleStateName] = stageJump.toIdleState
        end 
    end

    TryLoad( StageClipNames.Idle,        stageJson_.clipSrcs.animClipPath_Idle      )
    TryLoad( StageClipNames.Idle2,       stageJson_.clipSrcs.animClipPath_Idle_2     )
    TryLoad( StageClipNames.Interact_1,  stageJson_.clipSrcs.animClipPath_Simple_1  )
    TryLoad( StageClipNames.Interact_2,  stageJson_.clipSrcs.animClipPath_Simple_2  )
    TryLoad( StageClipNames.Interact_3,  stageJson_.clipSrcs.animClipPath_Simple_3  )
    TryLoad( StageClipNames.Interact_4,  stageJson_.clipSrcs.animClipPath_Simple_4  )
    TryLoad( StageClipNames.Interact_5,  stageJson_.clipSrcs.animClipPath_Simple_5  )
    TryLoad( StageClipNames.Interact_6,  stageJson_.clipSrcs.animClipPath_Simple_6  )
    TryLoad( StageClipNames.Interact_7,  stageJson_.clipSrcs.animClipPath_Simple_7  )
    TryLoad( StageClipNames.Interact_8,  stageJson_.clipSrcs.animClipPath_Simple_8  )
    TryLoad( StageClipNames.Interact_9,  stageJson_.clipSrcs.animClipPath_Simple_9  )
    TryLoad( StageClipNames.Interact_10,  stageJson_.clipSrcs.animClipPath_Simple_10  )
end





--[[
    用 key 来激活禁用某个 iState:
    目前这一版设计中, 是最简单最基础的方案: 任何一个 key 都能开启or禁用这个 iState; 
    未来可能的拓展:
        每个 iState 都需要所有 key 都禁用了, 才能被禁用;
    但目前这版实现 (最初版) 尚未证明 "无法覆盖所有可能性", 所以暂时先用着...
]]
---@param node_ table @ iState or uiNode 
function IdolLive3D_BaseParamsJsonDataV2:_BindActiveKeyEvent( node_, funcList_ ) 
    if #node_.activeKeyMgr.nodes == 0 then 
        return
    end    
    table.insert(funcList_, function(key_,isActive_) 
        for _,node in pairs(node_.activeKeyMgr.nodes) do 
            local key = node.key
            local type = node.activeType
            if key_ == key then 
                if isActive_ == true then 
                    if type == IdolLive3D_States.ActiveKeyType.T_BothOpenAndClose or type == IdolLive3D_States.ActiveKeyType.T_OnlyOpen then 
                        node_.isCurrentActive = true
                        return
                    end
                else 
                    if type == IdolLive3D_States.ActiveKeyType.T_BothOpenAndClose or type == IdolLive3D_States.ActiveKeyType.T_OnlyClose then 
                        node_.isCurrentActive = false
                        return
                    end
                end 
            end 
        end 
    end)
end



