-- 处理单个 loader
function IdolLive3D_BaseParamsJsonDataV2:ReadSingleStageAssets( loaderKey_, loader_ )
    local runtimeRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Runtime_")

    ---@return table | nil
    local FindStageJson = function( stagesJson_, stageName_ )
        assert( string.isEmpty(stageName_) == false )
        for k,v in pairs(stagesJson_) do
            if v.stageName == stageName_ then 
                return v
            end
        end 
        return nil
    end

    --- =============
    local key = IdolLive3D_UtilsV2.IsKeyStartWith( loaderKey_, IdolLive3D_StatesV2.loaderHead_Stage ) -- 返回剥离后的字符串 | nil
    if isNull(key) then
        return
    end

    ---
    local parts = string.split2(key, ".")
    local keyStageName = parts[1] -- stageName; 如: "100"
    local keyClipName  = parts[2] -- clipName;  如: "Idle", "ToIdle_200", "SimpleFX_101"
    assert( string.isEmpty(keyStageName) == false and string.isEmpty(keyClipName) == false )

    ---
    local stageJson = FindStageJson( self.data.stages, keyStageName )
    assert( isNotNull(stageJson) )

    --- 初始化容器
    stageJson.simpleFxTFMaps = {}


    local simpleFXName = IdolLive3D_UtilsV2.IsKeyStartWith( keyClipName, IdolLive3D_StatesV2.loaderHead_SimpleFX ) -- 返回剥离后的字符串 | nil
    if isNotNull(simpleFXName) then  -- "101"
        -- ================= 说明本 loader 是个 simpleIState 的 fx ===============
        local fxGO = loader_:Instantiate()
        fxGO.transform:SetParent( runtimeRootTF )
        fxGO.transform:SetPositionAndRotation( Vector3.zero, Quaternion.identity)
        stageJson.simpleFxTFMaps[simpleFXName] = fxGO.transform
       
        ---
        local tgtIState = stageJson.name_to_InteractiveStates[simpleFXName]
        if isNotNull(tgtIState) then 
            assert( tgtIState.stateType == StateType.Simple )
            tgtIState.fxTF = fxGO.transform
            KTool.SetActive( fxGO, false )
        else 
            printError( "没找到 simple fx 对应的 iState; simpleFXName = " .. tostring(simpleFXName) )
        end 

    else 
        local tgtStageName = IdolLive3D_UtilsV2.IsKeyStartWith( keyClipName, IdolLive3D_StatesV2.loaderHead_ToIdle ) -- 返回剥离后的字符串 | nil
        if isNotNull(tgtStageName) then -- "200"
            -- ================= 说明本 loader 是个 ToIdle 的 clip ===============
            assert( string.isEmpty(tgtStageName) == false )

            local animationClip = GameObject.Instantiate(loader_.ResultObject)
            loader_:Retain(animationClip) -- 防止 clip 被释放
            
            local stageJump = stageJson.stageJumps[tgtStageName]
            assert( isNotNull(stageJump) )
            stageJump.animClipGO = animationClip -- !! 不是每个 stageJump 都有 animClipGO

        else
            -- ================= 说明本 loader 是 Idle 等... ===============
            assert( string.isEmpty(keyClipName) == false )

            local animationClip = GameObject.Instantiate(loader_.ResultObject)
            loader_:Retain(animationClip) -- 防止 clip 被释放

            stageJson.animClips[keyClipName] = animationClip
            -- !!! 未来再来完善...
        end
    end 
end



