---@param buildsRootTF_ UnityEngine.Transform 
---@param sceneNode_ table @ json node
function IdolLive3D_BaseParamsJsonDataV2._FindSceneNodeGO( buildsRootTF_, sceneNode_ )
    assert( string.isEmpty(sceneNode_.path) == false )
    ---
    local path = sceneNode_.path:gsub("^[^/]+", IdolLive3D_StatesV2.SceneBuildName) -- 强制替换第一个 '/' 之前的name
    ---
    local nodeTF = buildsRootTF_:Find( path )
    if isNotNull(nodeTF) then 
        sceneNode_.transform = nodeTF
    else 
        printError("没找到目标 scene node, path:" .. tostring(path))
        sceneNode_.transform = nil
    end 
end


---@param isEnterNewStageOrClip_ boolean @ true: 表示正在进入某个 stage / clip;  false: 表示正在离开某个 stage / clip
function IdolLive3D_BaseParamsJsonDataV2.HandleSceneNodes( sceneNodesMgr_, isEnterNewStageOrClip_ )
    assert( type(sceneNodesMgr_.sceneNodes) == "table" )
    local NodeShowType = IdolLive3D_States.NodeShowType

    for _,node in pairs(sceneNodesMgr_.sceneNodes) do
        if isNotNull(node.transform) then
            if isEnterNewStageOrClip_ == true then 
                if node.nodeShowType==NodeShowType.T_Open or node.nodeShowType==NodeShowType.T_Open_Hide then 
                    print("进入时 开启 sceneNode:" .. table.dump( checkTable(node) ) )
                    KTool.SetActive( node.transform.gameObject, true)
                else    
                    print("进入时 关闭 sceneNode:" .. table.dump( checkTable(node) ) )
                    KTool.SetActive( node.transform.gameObject, false)
                end 

            else 
                if node.nodeShowType==NodeShowType.T_Hide_Open or node.nodeShowType==NodeShowType.T_Open_Hide then 
                    if node.nodeShowType==NodeShowType.T_Hide_Open then 
                        print("离开时 开启 sceneNode:" .. table.dump( checkTable(node) ) )
                        KTool.SetActive( node.transform.gameObject, true)
                    else 
                        print("离开时 关闭 sceneNode:" .. table.dump( checkTable(node) ) )
                        KTool.SetActive( node.transform.gameObject, false)
                    end 
                end                 
            end
        else 
            printError("发现 scene node transform 为空; node:" .. table.dump( node ) )
        end
    end
end


