function IdolLive3D_BaseParamsJsonDataV2._Prepare_FreeCameraActiveSpatialRange( freeCameraActiveSpatialRange_ )
    local r = freeCameraActiveSpatialRange_
    --- yaw: 
    if r.yaw.range > 360 then 
        r.yaw.isUse = false
    end 
    if r.yaw.isUse == true then
        r.yaw.dir = Quaternion.Euler(0,r.yaw.dirDegree,0) * Vector3.forward
        local halfRange = r.yaw.range * 0.5
        r.yaw.leftDir  = Quaternion.Euler(0,-halfRange,0) * r.yaw.dir
        r.yaw.rightDir = Quaternion.Euler(0, halfRange,0) * r.yaw.dir
    end
    --- pitch:
    if r.pitch.from < 0.0001 and r.pitch.to > 0.99999 then 
        r.pitch.isUse = false
    end 
    --- zoom:
    if r.zoom.from < 0.0001 and r.zoom.to > 0.99999 then 
        r.zoom.isUse = false
    end 
end



