function IdolLive3D_BaseParamsJsonDataV2:_CheckSuperTimelineClipLeaves( clip_ ) 

    assert(isTable(clip_.leaveInfos))
    assert(isTable(clip_.nextClipInfos))
    local leaveInfosNum     = table.count(clip_.leaveInfos)
    local nextClipInfosNum  = table.count(clip_.nextClipInfos)

    if (leaveInfosNum + nextClipInfosNum) == 0 then 
        printError("leaveInfos 和 nextClipInfos 至少要配置一个; 请修改 json 文件")
        return
    end 


    --- 快捷容器
    clip_.leaveInfosMap = {} -- k:conditionKey; v:leaveInfo
    for _,e in pairs(clip_.leaveInfos) do 
        if IdolLive3D_Utils.IsKeyValid(e.conditionKey) then 
            clip_.leaveInfosMap[string.lower(e.conditionKey)] = e
        end 
    end
    --- 快捷容器
    clip_.nextClipInfosMap = {} -- k:conditionKey; v:nextClipInfo
    for _,e in pairs(clip_.nextClipInfos) do 
        if IdolLive3D_Utils.IsKeyValid(e.conditionKey) then 
            clip_.nextClipInfosMap[string.lower(e.conditionKey)] = e
        end
    end


    -- 找到 自动离开的 node:
    local autoLeaveNode = nil 
    for _,e in pairs(clip_.leaveInfos) do 
        if not (e.leaveMode == IdolLive3D_States.SuperTimelineLeaveMode.FullScreenFX or e.leaveMode == IdolLive3D_States.SuperTimelineLeaveMode.Smooth) then 
            printError("superTimeline leaveMode 配置出错")
            e.leaveMode = IdolLive3D_States.SuperTimelineLeaveMode.FullScreenFX
        end 
        ---
        if e.conditionKey == "" then 
            if autoLeaveNode == nil then 
                autoLeaveNode = e
            else 
                printError("发现两个以上 可以自动离开的 leaveInfo; 请修改 json 文件")
            end 
        end 
    end 
    ---
    local autoNextClipNode = nil 
    for _,e in pairs(clip_.nextClipInfos) do 
        if e.conditionKey == "" then 
            if autoNextClipNode == nil then 
                autoNextClipNode = e
            else 
                printError("发现两个以上 可以自动离开的 nextClipInfos; 请修改 json 文件")
            end 
        end 
    end 
    ---
    if isNotNull(autoLeaveNode) and isNotNull(autoNextClipNode) then 
        printError("可自动离开的 leaveInfo 和 nextClipInfo, 一共只能存在一个, 请修改 json 文件")
    end 

    clip_.autoLeaveInfo = autoLeaveNode         -- may nil
    clip_.autoNextClipInfo = autoNextClipNode   -- may nil

end



function IdolLive3D_BaseParamsJsonDataV2:_CollectSuperTimelineAllConditionKeys( superTimelineIState_ ) 
    local rets = {} -- map: k:strKey, v:nil or 1
    for __,clip in pairs(superTimelineIState_.allClips) do
        for _,e in pairs(clip.nextClipInfos) do 
            if IdolLive3D_Utils.IsKeyValid(e.conditionKey) then 
                rets[string.lower(e.conditionKey)] = 1 -- 消除重复元素
            end
        end
        for _,e in pairs(clip.leaveInfos) do 
            if IdolLive3D_Utils.IsKeyValid(e.conditionKey) then 
                rets[string.lower(e.conditionKey)] = 1 -- 消除重复元素
            end
        end
    end
    return rets
end

function IdolLive3D_BaseParamsJsonDataV2:_CollectStageAllTouchKeys( stageJson_ ) 
    local rets = {} -- map: k:strKey, v:nil or 1
    for _,iState in pairs(stageJson_.simpleInteractiveStates) do 
        if IdolLive3D_Utils.IsKeyValid(iState.touchKey) then 
            --table.insert( rets, iState.touchKey )
            rets[string.lower(iState.touchKey)] = 1 -- 消除重复元素
        end 
    end
    for _,key in pairs(stageJson_.superTimelineKeys) do 
        local superTL = self:_FindSuperTimelineByKey(key)
        assert( isNotNull(superTL) )
        if IdolLive3D_Utils.IsKeyValid(superTL.touchKey) then 
            --table.insert( rets, superTL.touchKey )
            rets[string.lower(superTL.touchKey)] = 1 -- 消除重复元素
        end 
    end 
    return rets
end




function IdolLive3D_BaseParamsJsonDataV2:_PrepareIKParam( ikParam )

    if string.isEmpty(ikParam.ikRegionDatas) then 
        printError("json 数据异常, ikRegionDatas 为空")
        return
    end 
    if ikParam.iKRegionType == 0 then 
        printError("json 数据异常, ikParam.iKRegionType 为空")
        return
    end 

    ikParam.totalPlayTimes = 0 -- 进入本次 深度互动以来, 本 ik 被 play 的次数;

    ikParam.ikRegionJson = table.deserialize(ikParam.ikRegionDatas) -- 已经是 json 层次化结构了;
    local ikRegionJson = ikParam.ikRegionJson

    if ikParam.iKRegionType == IdolLive3D_StatesV2.IKRegionType.Arc then 

        -- 计算 弧线两端点:
        local halfAngle = ikRegionJson.arcAngle * 0.5 
        local zxRatio = ikRegionJson.radiusZ / ikRegionJson.radiusX

        local aPosLS = Quaternion.AngleAxis(-halfAngle,Vector3.up) * (Vector3.forward * ikRegionJson.radiusX)
        local bPosLS = Quaternion.AngleAxis( halfAngle,Vector3.up) * (Vector3.forward * ikRegionJson.radiusX)
        aPosLS.z = aPosLS.z * zxRatio
        bPosLS.z = bPosLS.z * zxRatio
        local midPosLS = (aPosLS+bPosLS) * 0.5

        if ikRegionJson.arcAngle > 180.0 then 
            local tmp = aPosLS
            aPosLS = bPosLS
            bPosLS = tmp
            midPosLS = midPosLS * -1
        end 

        ikRegionJson.aPosLS = aPosLS
        ikRegionJson.bPosLS = bPosLS
    end


    -- 去除掉不合规的 interactRegionNodes:
    local tmpList = {}
    for i=1, #ikRegionJson.interactRegionNodes do 
        local node = ikRegionJson.interactRegionNodes[i]
        if IdolLive3D_Utils.IsKeyValid(node.key) then 
            table.insert( tmpList, node )
        end 
    end 
    ikRegionJson.interactRegionNodes = tmpList


end




return IdolLive3D_BaseParamsJsonDataV2